// books.js — 管理员图书管理：检索、筛选、新增、编辑、删除，以及分类维护。
import { api } from "../api.js";
import {
  esc, loading, renderTable, openModal, confirmDialog, toast, formValues, fillForm, badge,
} from "../components.js";

let categories = [];

function categoryName(id) {
  if (!id) return "未分类";
  const c = categories.find((x) => x.id === id);
  return c ? c.name : "未分类";
}

function bookForm(book) {
  const form = document.createElement("form");
  const catOptions = categories
    .map((c) => `<option value="${c.id}">${esc(c.name)}</option>`)
    .join("");
  form.innerHTML = `
    <div class="form-row">
      <div class="field"><label>ISBN</label><input class="input" name="isbn" /></div>
      <div class="field"><label>分类</label>
        <select class="input" name="categoryId"><option value="">未分类</option>${catOptions}</select></div>
    </div>
    <div class="field"><label>书名</label><input class="input" name="title" required /></div>
    <div class="form-row">
      <div class="field"><label>作者</label><input class="input" name="author" /></div>
      <div class="field"><label>出版社</label><input class="input" name="publisher" /></div>
    </div>
    <div class="form-row">
      <div class="field"><label>馆藏位置</label><input class="input" name="location" /></div>
      <div class="field"><label>总册数</label><input class="input" type="number" name="totalQty" min="1" value="1" required /></div>
    </div>`;
  if (book) {
    fillForm(form, {
      ...book,
      categoryId: book.categoryId ?? "",
    });
  }
  return form;
}

async function openBookEditor(book, reload) {
  const isEdit = !!book;
  const form = bookForm(book);
  const footer = document.createElement("div");
  const btnCancel = document.createElement("button");
  btnCancel.className = "btn btn-ghost";
  btnCancel.textContent = "取消";
  const btnSave = document.createElement("button");
  btnSave.className = "btn btn-primary";
  btnSave.textContent = "保存";
  footer.append(btnCancel, btnSave);

  const m = openModal({ title: isEdit ? "编辑图书" : "新增图书", body: form, footer });
  btnCancel.onclick = m.close;
  btnSave.onclick = async () => {
    const v = formValues(form);
    if (!v.title) { toast("请填写书名", "error"); return; }
    v.totalQty = Number(v.totalQty) || 1;
    v.categoryId = v.categoryId ? Number(v.categoryId) : null;
    btnSave.disabled = true;
    try {
      if (isEdit) {
        v.availableQty = book.availableQty;
        await api.updateBook(book.id, v);
        toast("图书已更新", "success");
      } else {
        v.availableQty = v.totalQty;
        await api.createBook(v);
        toast("图书已新增", "success");
      }
      m.close();
      reload();
    } catch (err) {
      toast(err.message, "error");
      btnSave.disabled = false;
    }
  };
}

async function openCategoryManager(reload) {
  const body = document.createElement("div");
  body.innerHTML = `
    <div class="toolbar">
      <input class="input" id="new-cat" placeholder="输入新分类名称" />
      <button class="btn btn-primary btn-sm" id="add-cat">新增分类</button>
    </div>
    <div class="table-wrap" id="cat-list"></div>`;
  const listEl = body.querySelector("#cat-list");
  listEl.innerHTML = `<table class="data"><thead><tr><th>分类名称</th><th style="text-align:right">编号</th></tr></thead>
    <tbody>${categories.map((c) => `<tr><td>${esc(c.name)}</td><td style="text-align:right">${c.id}</td></tr>`).join("")}</tbody></table>`;

  const m = openModal({ title: "分类管理", body, size: "lg" });
  body.querySelector("#add-cat").onclick = async () => {
    const name = body.querySelector("#new-cat").value.trim();
    if (!name) { toast("请填写分类名称", "error"); return; }
    try {
      await api.addCategory(name);
      toast("分类已新增", "success");
      m.close();
      reload();
    } catch (err) { toast(err.message, "error"); }
  };
}

export async function renderBooks(container) {
  loading(container);
  categories = await api.listCategories();

  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="toolbar">
      <input class="input" id="kw" placeholder="搜索书名 / 作者 / ISBN" />
      <select class="input" id="cat" style="min-width:140px">
        <option value="">全部分类</option>
        ${categories.map((c) => `<option value="${c.id}">${esc(c.name)}</option>`).join("")}
      </select>
      <button class="btn btn-primary btn-sm" id="search">查询</button>
      <div class="spacer"></div>
      <button class="btn btn-outline btn-sm" id="manage-cat">分类管理</button>
      <button class="btn btn-primary btn-sm" id="add-book">+ 新增图书</button>
    </div>
    <div id="table"></div>`;
  container.innerHTML = "";
  container.appendChild(wrap);

  const tableEl = wrap.querySelector("#table");
  const load = async () => {
    loading(tableEl);
    const keyword = wrap.querySelector("#kw").value.trim();
    const category = wrap.querySelector("#cat").value;
    const books = await api.listBooks({ keyword, category });
    tableEl.innerHTML = "";
    renderTable(
      tableEl,
      [
        { key: "title", title: "书名", render: (r) =>
          `<div>${esc(r.title)}</div><div class="muted" style="font-size:12px">${esc(r.isbn)}</div>` },
        { key: "author", title: "作者" },
        { key: "category", title: "分类", render: (r) => badge(categoryName(r.categoryId), "blue") },
        { key: "location", title: "位置" },
        {
          key: "availableQty", title: "可借/总册", align: "center",
          render: (r) => `${r.availableQty} / ${r.totalQty}`,
        },
        {
          title: "操作", align: "right",
          render: (r) => `
            <div class="row-actions">
              <button class="btn btn-ghost btn-sm act-edit">编辑</button>
              <button class="btn btn-danger btn-sm act-del">删除</button>
            </div>`,
        },
      ],
      books
    );

    tableEl.querySelectorAll(".act-edit").forEach((b) =>
      b.addEventListener("click", () => {
        const book = books[Number(b.closest("tr").rowIndex) - 1];
        openBookEditor(book, () => renderBooks(container));
      })
    );
    tableEl.querySelectorAll(".act-del").forEach((b) =>
      b.addEventListener("click", async () => {
        const book = books[Number(b.closest("tr").rowIndex) - 1];
        if (await confirmDialog(`确定删除《${book.title}》吗？存在未还借阅时将无法删除。`)) {
          try {
            await api.deleteBook(book.id);
            toast("图书已删除", "success");
            renderBooks(container);
          } catch (err) { toast(err.message, "error"); }
        }
      })
    );
  };

  wrap.querySelector("#search").onclick = load;
  wrap.querySelector("#kw").addEventListener("keydown", (e) => { if (e.key === "Enter") load(); });
  wrap.querySelector("#add-book").onclick = () => openBookEditor(null, () => renderBooks(container));
  wrap.querySelector("#manage-cat").onclick = () => openCategoryManager(() => renderBooks(container));

  load();
}

// borrows.js — 管理员借阅管理：在借/历史查询、办理借阅、办理归还（含逾期罚款）。
import { api } from "../api.js";
import {
  esc, loading, renderTable, openModal, confirmDialog, toast, formValues, badge,
} from "../components.js";

function stateBadge(r) {
  if (r.status === "returned") return badge("已归还", "gray");
  if (r.state && r.state.includes("逾期")) return badge(r.state, "red");
  return badge(r.state || "正常", "green");
}

function borrowForm(readers, books) {
  const form = document.createElement("form");
  form.innerHTML = `
    <div class="field"><label>读者</label>
      <select class="input" name="readerId" required>
        <option value="">请选择读者</option>
        ${readers.filter((r) => r.status === "active").map(
    (r) => `<option value="${r.userId}">${esc(r.readerNo)} ${esc(r.name)}</option>`
  ).join("")}
      </select></div>
    <div class="field"><label>图书</label>
      <select class="input" name="bookId" required>
        <option value="">请选择图书</option>
        ${books.filter((b) => b.availableQty > 0).map(
    (b) => `<option value="${b.id}">${esc(b.title)}（可借 ${b.availableQty}）</option>`
  ).join("")}
      </select></div>`;
  return form;
}

export async function renderBorrows(container) {
  loading(container);
  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="login-tabs" style="max-width:340px">
      <button data-t="active" class="active">在借图书</button>
      <button data-t="history">历史记录</button>
    </div>
    <div class="toolbar">
      <div class="spacer"></div>
      <button class="btn btn-primary btn-sm" id="add-borrow">+ 办理借阅</button>
    </div>
    <div id="table"></div>`;
  container.innerHTML = "";
  container.appendChild(wrap);
  const tableEl = wrap.querySelector("#table");
  let mode = "active";

  const columnsActive = [
    { key: "readerNo", title: "读者编号" },
    { key: "readerName", title: "读者" },
    { key: "title", title: "书名" },
    { key: "borrowDate", title: "借出日期" },
    { key: "dueDate", title: "应还日期" },
    { key: "renewCount", title: "续借", align: "center", render: (r) => `${r.renewCount} 次` },
    { title: "状态", align: "center", render: stateBadge },
    {
      title: "操作", align: "right",
      render: (r) => `<div class="row-actions"><button class="btn btn-primary btn-sm act-return">办理归还</button></div>`,
    },
  ];
  const columnsHistory = [
    { key: "readerNo", title: "读者编号" },
    { key: "readerName", title: "读者" },
    { key: "title", title: "书名" },
    { key: "borrowDate", title: "借出日期" },
    { key: "returnDate", title: "归还日期" },
    { key: "renewCount", title: "续借次数", align: "center" },
    {
      key: "fine", title: "罚款(元)", align: "right",
      render: (r) => (r.fine > 0 ? `<span style="color:var(--danger)">${r.fine.toFixed(2)}</span>` : "0.00"),
    },
    { title: "状态", align: "center", render: stateBadge },
  ];

  const load = async () => {
    loading(tableEl);
    const recs = mode === "active" ? await api.activeBorrows() : await api.historyBorrows();
    tableEl.innerHTML = "";
    renderTable(tableEl, mode === "active" ? columnsActive : columnsHistory, recs);

    tableEl.querySelectorAll(".act-return").forEach((b) =>
      b.addEventListener("click", async () => {
        const r = recs[Number(b.closest("tr").rowIndex) - 1];
        const overdue = r.state && r.state.includes("逾期");
        if (await confirmDialog(`确定为 ${r.readerName} 归还《${r.title}》吗？${overdue ? "该图书已逾期，将计算罚款。" : ""}`,
          { okText: "归还" })) {
          try {
            const res = await api.returnBook(r.id);
            if (res.fine > 0) {
              openModal({
                title: "归还成功",
                body: `<p>《${esc(r.title)}》已归还。</p>
                  <p>逾期罚款：<span style="color:var(--danger);font-size:18px;font-weight:700">${Number(res.fine).toFixed(2)} 元</span></p>`,
                footer: "",
              });
            } else {
              toast("归还成功", "success");
            }
            load();
          } catch (err) { toast(err.message, "error"); }
        }
      })
    );
  };

  wrap.querySelectorAll(".login-tabs button").forEach((b) =>
    b.addEventListener("click", () => {
      wrap.querySelectorAll(".login-tabs button").forEach((x) => x.classList.remove("active"));
      b.classList.add("active");
      mode = b.dataset.t;
      load();
    })
  );

  wrap.querySelector("#add-borrow").onclick = async () => {
    const [readers, books] = await Promise.all([api.listReaders(), api.listBooks()]);
    const form = borrowForm(readers, books);
    const footer = document.createElement("div");
    const btnCancel = document.createElement("button");
    btnCancel.className = "btn btn-ghost"; btnCancel.textContent = "取消";
    const btnSave = document.createElement("button");
    btnSave.className = "btn btn-primary"; btnSave.textContent = "办理";
    footer.append(btnCancel, btnSave);
    const m = openModal({ title: "办理借阅", body: form, footer });
    btnCancel.onclick = m.close;
    btnSave.onclick = async () => {
      const v = formValues(form);
      if (!v.readerId || !v.bookId) { toast("请选择读者与图书", "error"); return; }
      try {
        await api.createBorrow(Number(v.readerId), Number(v.bookId));
        toast("借阅成功", "success");
        m.close();
        mode = "active";
        wrap.querySelectorAll(".login-tabs button").forEach((x) => x.classList.toggle("active", x.dataset.t === "active"));
        load();
      } catch (err) { toast(err.message, "error"); }
    };
  };

  load();
}
